import urllib.request
import urllib.error

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    class RateLimitError(Exception):
        pass

    class ServerError(Exception):
        pass

    class ClientError(Exception):
        pass

    class ConnectionError(Exception):
        pass

    def get(self, path):
        url = self.base_url + path
        req = urllib.request.Request(url)
        backoff_delays = [0.5, 1, 2]

        # Helper to handle URLError
        def handle_network_error():
            try:
                return urllib.request.urlopen(req, timeout=self.timeout)
            except urllib.error.URLError:
                raise APIClient.ConnectionError

        # Initial request
        try:
            response = urllib.request.urlopen(req, timeout=self.timeout)
        except urllib.error.HTTPError as e:
            status = e.code
            if status == 429:
                for i, delay in enumerate(backoff_delays):
                    try:
                        response = urllib.request.urlopen(req, timeout=self.timeout)
                        break
                    except urllib.error.HTTPError as e2:
                        if i == len(backoff_delays) - 1:
                            raise APIClient.RateLimitError
            elif 500 <= status < 600:
                try:
                    response = urllib.request.urlopen(req, timeout=self.timeout)
                except urllib.error.HTTPError as e2:
                    raise APIClient.ServerError
            else:  # 4xx (except 429)
                raise APIClient.ClientError
        except urllib.error.URLError:
            try:
                response = urllib.request.urlopen(req, timeout=self.timeout)
            except urllib.error.URLError:
                raise APIClient.ConnectionError

        # Read and return response body
        return response.read().decode('utf-8')
